/**
 * Purges all sample and demo data (matches, balls, players, playerMatchStats) from Firestore.
 */
export async function purgeAllDemoData(): Promise<{ deletedMatches: number; deletedPlayers: number }> {
  let deletedMatches = 0;
  let deletedPlayers = 0;

  try {
    // 1. Purge Demo Matches & their ball subcollections
    const matchesSnap = await getDocs(collection(db, MATCHES_COLLECTION));
    for (const matchDoc of matchesSnap.docs) {
      const matchId = matchDoc.id;
      const data = matchDoc.data();

      const title = (data.title || '').toString();
      const teamAName = (data.teamA?.name || '').toString();
      const teamBName = (data.teamB?.name || '').toString();

      const isDemo =
        DEMO_MATCH_IDS.includes(matchId) ||
        matchId.startsWith('match_live_') ||
        matchId.startsWith('match_up_') ||
        matchId.startsWith('match_completed_') ||
        matchId.startsWith('demo_') ||
        matchId.startsWith('match_demo_') ||
        matchId.startsWith('match_test_') ||
        matchId.startsWith('match_sample_') ||
        data.isDemo === true ||
        title.includes('Lions') ||
        title.includes('Eagles') ||
        title.includes('Demo') ||
        title.includes('Sample') ||
        title.startsWith('Match ') ||
        (teamAName.includes('Metro Challengers') && teamBName.includes('Local XI 5') && matchId.startsWith('match_'));

      if (isDemo) {
        try {
          const ballsSnap = await getDocs(collection(db, MATCHES_COLLECTION, matchId, 'balls'));
          for (const bDoc of ballsSnap.docs) {
            await deleteDoc(doc(db, MATCHES_COLLECTION, matchId, 'balls', bDoc.id));
          }
        } catch (e) {
          console.warn(`Could not delete balls for demo match ${matchId}:`, e);
        }

        await deleteDoc(doc(db, MATCHES_COLLECTION, matchId));
        deletedMatches++;
      }
    }

    // 2. Purge Demo Players
    const playersSnap = await getDocs(collection(db, PLAYERS_COLLECTION));
    for (const pDoc of playersSnap.docs) {
      const pId = pDoc.id;
      const pData = pDoc.data();
      const fullName = (pData.fullName || '').toString().trim();

      const isDemoPlayer =
        DEMO_PLAYER_IDS.includes(pId) ||
        pId.startsWith('player_ref_') ||
        pId.startsWith('demo_') ||
        pId.startsWith('player_demo_') ||
        pId.startsWith('p_batter_') ||
        pId.startsWith('p_bowler_') ||
        pId.startsWith('p_solo') ||
        pData.isDemo === true ||
        DEMO_PLAYER_NAMES.includes(fullName);

      if (isDemoPlayer) {
        await deleteDoc(doc(db, PLAYERS_COLLECTION, pId));
        deletedPlayers++;
      }
    }

    // 3. Purge orphaned or demo playerMatchStats
    try {
      const statsSnap = await getDocs(collection(db, STATS_COLLECTION));
      for (const sDoc of statsSnap.docs) {
        const sData = sDoc.data();
        if (
          DEMO_PLAYER_IDS.includes(sData.playerId) ||
          DEMO_MATCH_IDS.includes(sData.matchId) ||
          (sData.playerName && DEMO_PLAYER_NAMES.includes(sData.playerName.trim()))
        ) {
          await deleteDoc(doc(db, STATS_COLLECTION, sDoc.id));
        }
      }
    } catch (e) {
      console.warn('Could not clean demo stats:', e);
    }
  } catch (err) {
    console.error('Error during demo data purge:', err);
  }

  return { deletedMatches, deletedPlayers };
}

/**
 * Purges ALL data from matches, players, and stats collections (Total clean reset).
 */
export async function purgeAllDataCompletely(): Promise<{ deletedMatches: number; deletedPlayers: number }> {
  let deletedMatches = 0;
  let deletedPlayers = 0;

  try {
    const matchesSnap = await getDocs(collection(db, MATCHES_COLLECTION));
    for (const mDoc of matchesSnap.docs) {
      try {
        const ballsSnap = await getDocs(collection(db, MATCHES_COLLECTION, mDoc.id, 'balls'));
        for (const bDoc of ballsSnap.docs) {
          await deleteDoc(doc(db, MATCHES_COLLECTION, mDoc.id, 'balls', bDoc.id));
        }
      } catch {}
      await deleteDoc(doc(db, MATCHES_COLLECTION, mDoc.id));
      deletedMatches++;
    }

    const playersSnap = await getDocs(collection(db, PLAYERS_COLLECTION));
    for (const pDoc of playersSnap.docs) {
      await deleteDoc(doc(db, PLAYERS_COLLECTION, pDoc.id));
      deletedPlayers++;
    }

    try {
      const statsSnap = await getDocs(collection(db, STATS_COLLECTION));
      for (const sDoc of statsSnap.docs) {
        await deleteDoc(doc(db, STATS_COLLECTION, sDoc.id));
      }
    } catch {}
  } catch (err) {
    console.error('Error during complete data purge:', err);
  }

  return { deletedMatches, deletedPlayers };
}

