/**
 * Initial data seeder is enabled if players collection is empty.
 */
export async function seedInitialDataIfEmpty(): Promise<boolean> {
  try {
    const { collection, getDocs } = await import('firebase/firestore');
    const snap = await getDocs(collection(db, PLAYERS_COLLECTION));
    if (snap.empty) {
      await seedDemoCricketData();
      return true;
    }
  } catch (e) {
    console.error('Failed to check or seed initial data:', e);
  }
  return false;
}


